def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Simple approach: find first difference and determine what needs to change
    if s_in == s_out:
        return None

    # Find first position where they differ
    pos = 0
    while pos < len(s_in) and pos < len(s_out) and s_in[pos] == s_out[pos]:
        pos += 1

    if pos >= len(s_in) or pos >= len(s_out):
        # One string is prefix of other
        if len(s_in) > len(s_out):
            return (s_in[pos:], "", pos)
        else:
            return ("", s_out[pos:], pos)

    # Find end of the differing part
    end_in = pos
    end_out = pos
    while end_in < len(s_in) and end_out < len(s_out) and s_in[end_in] == s_out[end_out]:
        end_in += 1
        end_out += 1

    old_sub = s_in[pos:end_in]
    new_sub = s_out[pos:end_out]

    return (old_sub, new_sub, pos)

# Analyze each changed pair
changed = [(0, 'adizg', 'adifg'), (1, 'egvz', 'chf'), (4, 'cdfeck', 'cdfeugck')]

for idx, inp, outp in changed:
    result = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}' | Edit: {result}")

